mapper.select:
select a.*,coalesce(u.name,t.name) authorName,coalesce(u.avatar,t.avatar) authorAvatar from article a left join `user` u on a.user_id=u.id left join `teacher` t on a.user_id=t.id and u.id is null

  and a.title like concat('%',#{title},'%')
  and a.category=#{category}
  and a.user_id=#{userId}
  and a.status=#{status}

order by a.create_time desc
